def max_consecutive_digits(num):
    max_count = 0
    current_count = 1
    for i in range(1, len(num)):
        if num[i] == num[i-1]:
            current_count += 1
        else:
            current_count = 1
        if current_count > max_count:
            max_count = current_count
    return max_count

def rearrange_max_odd(s):
    first = s.find('1')
    if first == -1:
        return ""  # According to problem constraints, there is at least one '1'
    second = s.find('0', first + 1)
    return '1' + '0' * (second - first - 1)

def shortest_subarray(nums, target):
    prefix_sums = {0: -1}
    current_sum = 0
    min_length = float('inf')
    for i in range(len(nums)):
        current_sum += nums[i]
        target = target
        if (current_sum - target) in prefix_sums:
            length = i - prefix_sums[current_sum - target]
            if length < min_length:
                min_length = length
        if current_sum not in prefix_sums:
            prefix_sums[current_sum] = i
    return min_length if min_length != float('inf') else -1

def min_operations(s1, s2, s3):
    common = set(s1) & set(s2) & set(s3)
    counts = {c: 0 for c in common}
    for s in [s1, s2, s3]:
        for c in s:
            counts[c] += 1
    min_ops = 0
    for c in common:
        min_ops += min(counts[c], counts[c], counts[c])
    return min_ops

def find_peaks(mountain):
