    n = len(mountain)
    for i in range(1, n - 1):
        if mountain[i] > mountain[i - 1] and mountain[i] > mountain[i + 1]:
            peaks.append(i)
    return peaks

def find_smallest_missing_integer(nums):
    if not nums:
        return None  # According to constraints, nums.length >= 1
    current_sum = 0
    longest_prefix = 0
    prev = -1  # To handle the first element
    for num in nums:
        if num == prev:
            current_sum += num
            if current_sum > longest_prefix:
                longest_prefix = current_sum
            prev = num
        else:
            current_sum += num
            if current_sum > longest_prefix:
                longest_prefix = current_sum
    return longest_prefix

from collections import Counter

def frequency_of_max_frequency(nums):
    counts = Counter(nums)
    max_freq = max(counts.values())
    return sum(1 for v in counts.values() if v == max_freq)

def has_trailing_zero(nums):
    if len(nums) < 2:
        return False
    has_even = any(num % 2 == 0 for num in nums)
    return has_even

