# Constants
GRID_SIZE = 5
CHARACTER_START_X = 2
CHARACTER_START_Y = 2
CHARACTER_JUMP_X = -1
CHARACTER_JUMP_Y = -1

# Initialize the grid
grid = [['.' for _ in range(GRID_SIZE)] for _ in range(GRID_SIZE)]

# Place the character at the center
character_position = (GRID_SIZE // 2, GRID_SIZE // 2)
grid[character_position[0]][character_position[1]] = 'C'

# Place obstacles randomly
obstacles = [
    (random.randint(0, GRID_SIZE - 1), random.randint(0, GRID_SIZE - 1)),
    (random.randint(0, GRID_SIZE - 1), random.randint(0, GRID_SIZE - 1)),
    (random.randint(0, GRID_SIZE - 1), random.randint(0, GRID_SIZE - 1))
]

def print_grid(grid):
    for row in grid:
        print(' '.join(row))
    print()

def move_character(grid, position, direction):
    x, y = position
    if direction == 'up' and x > 0:
        x -= 1
    elif direction == 'down' and x < GRID_SIZE - 1:
        x += 1
    elif direction == 'left' and y > 0:
        y -= 1
    elif direction == 'right' and y < GRID_SIZE - 1:
        y += 1
    return (x, y)

def jump_over_obstacle(grid, position, obstacle_x, obstacle_y):
    x, y = position
    if grid[x][y] == '.':
        return True
    if obstacle_x == x and obstacle_y == y:
        return True
    if grid[x][y] == 'C':
        return True
    return False

def main():
    print("Welcome to the Grid Game!")
    print("Use 'up', 'down', 'left', 'right', 'jump' to move or 'j' to jump.")
    print("Type 'exit' to quit the game.")

    while True:
        print_grid(grid)
        print("Current position: " + str(character_position))
        print("Jump to the next obstacle or move to an empty space.")

        command = input("Enter your command: ").strip().lower()

        if command == 'exit':
            print("Thanks for playing!")
            break
        elif command == 'up':
            character_position = move_character(grid, character_position, 'up')
        elif command == 'down':
            character_position = move_character(grid, character_position, 'down')
        elif command == 'left':
            character_position = move_character(grid, character_position, 'left')
        elif command == 'right':
            character_position = move_character(grid, character_position, 'right')
        elif command == 'j':
            if jump_over_obstacle(grid, character_position, obstacle_x, obstacle_y):
                print("You jumped over an obstacle!")
                character_position = move_character(grid, character_position, 'up')
            else:
                print("You can't jump over an obstacle!")
        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()

