def longest_substring_with_two_distinct(s: str) -> int:
    char_count = {}
    left = 0
    max_length = 0
    distinct_count = 0

    for right in range(len(s)):
        char = s[right]
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
            distinct_count += 1

        while distinct_count > 2:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                del char_count[left_char]
                distinct_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

